    print(k, 'subrc', v['subrc'])
    for m in v['messages']: print('   ', m['type'], m['id'], m['number'], repr(m['text']), m['screen'])
    cust={c['KUNNR']:(c['CREDIT_LIMIT'],c['BLOCKED']) for c in v['tables']['ZCR_CUSTOMER']}
